	@Override
	public MCCallerPanelBridge createBridge(String id) {
		if (id.equals("MS.MSBCL1170.Srch01")) {
			return new MS_MSBCL1170_Srch01Bridge();
		}
		return super.createBridge(id);
	}
	/**
	 * [MS_MSBCL1170_Srch01]の定型処理のInnerClass
	 */
	protected class MS_MSBCL1170_Srch01Bridge extends MCCallerPanelBridge {
		/**
		 * 電文パラメータ<p>
		 * 
		 * 参照する場合には{@link #param()}を使用してください。
		 */
		MCParam p_MS_MSBCL1170_Srch01;

		/** コンストラクタ */
		protected MS_MSBCL1170_Srch01Bridge() {
			p_MS_MSBCL1170_Srch01 = new MCParam(PDef.MS_MSBCL1170_Srch01_INFO);
		}

		@Override
		public MCParam createAsyncParam() {
			MCParam param = new MCParam(PDef.MS_MSBCL1170_Srch01_INFO);
			param.setReqSrcId(getScreenID());
			// Up
			param.addUpBlock(mcframe.clientMSBC.MSBCP1170.CndR.create());
			// Down
			param.addDownBlock(MCList.create(mcframe.clientMSBC.MSBCP1170.DtlR.class));

			p_MS_MSBCL1170_Srch01 = param;
			return param;
		}

		/** パラメータを通信用に設定します。*/
		protected void setupParam() {
			p_MS_MSBCL1170_Srch01.setReqSrcId(getScreenID());
			setupUpParam();
			setupDownParam();
		}

		protected void setupUpParam() {
			p_MS_MSBCL1170_Srch01.addUpBlock(getCndR());
		}

		protected MCContainer up(int i) {
			return p_MS_MSBCL1170_Srch01.getContainerParam().getUpBlock(i);
		}
		
		protected MCContainer down(int i) {
			return p_MS_MSBCL1170_Srch01.getContainerParam().getDownBlock(i);
		}
		
		protected mcframe.clientMSBC.MSBCP1170.CndR up0() {
			return (mcframe.clientMSBC.MSBCP1170.CndR)up(0);
		}

		protected MCList<mcframe.clientMSBC.MSBCP1170.DtlR> down0() {
			return (MCList<mcframe.clientMSBC.MSBCP1170.DtlR>)down(0);
		}

		protected void setupDownParam() {
			p_MS_MSBCL1170_Srch01.addDownBlock(MCList.create(mcframe.clientMSBC.MSBCP1170.DtlR.class));
		}
		protected MCParam param() {
			return p_MS_MSBCL1170_Srch01;
		}

		protected void show() {
			setDtlL((MCList<mcframe.clientMSBC.MSBCP1170.DtlR>)p_MS_MSBCL1170_Srch01.getContainerParam().getDownBlock(0));
		}

		protected void clear() {
			getDtlL().clear();
		}
		
		protected List<MCContainer> getUpBlocks() {
			List<MCContainer> result = new ArrayList<MCContainer>();
			result.add(getCndR());
			return result;
		}
		
		protected List<MCContainer> getDownBlocks() {
			List<MCContainer> result = new ArrayList<MCContainer>();
			result.add(getDtlL());
			return result;
		}
	}
